  if (file.exists(audit_path)) {
    existing <- read.csv(audit_path, stringsAsFactors = FALSE)
    all_cols <- union(names(existing), names(audit))
    for (col in setdiff(all_cols, names(existing))) existing[[col]] <- NA
    for (col in setdiff(all_cols, names(audit))) audit[[col]] <- NA
    existing <- existing[, all_cols, drop = FALSE]
    audit <- audit[, all_cols, drop = FALSE]
    key_cols <- intersect(c("source_file", "family", "spec"), all_cols)
    if (length(key_cols) == 3L) {
      existing_key <- do.call(paste, c(existing[key_cols], sep = "\r"))
      audit_key <- do.call(paste, c(audit[key_cols], sep = "\r"))
      existing <- existing[!existing_key %in% audit_key, , drop = FALSE]
    }
    audit <- unique(rbind(existing, audit))
  }

  write.csv(audit, audit_path, row.names = FALSE)
  cat(sprintf(
    "  Weibull diagnostic audit written to %s (%d rows)\n",
    basename(audit_path), nrow(audit)
  ))
  invisible(audit)
}
